@if(!$room||!$subjectId)<x-ui.empty-state title="Pilih rombel dan mata pelajaran untuk mulai mengisi nilai."/>@else<form method="post" action="{{route('academic.grades.store')}}" class="card overflow-x-auto">@csrf<input type="hidden" name="academic_year_id" value="{{$year}}"><input type="hidden" name="semester_id" value="{{$semester}}"><input type="hidden" name="classroom_id" value="{{$room->id}}"><input type="hidden" name="academic_subject_id" value="{{$subjectId}}"><table class="table min-w-[750px]"><thead><tr><th class="w-12">No</th><th class="w-80">Siswa</th><th class="w-28">Nilai</th><th class="w-24">Predikat</th><th>Catatan</th></tr></thead><tbody>@foreach($students as $student)@php($grade=$grades->get($student->id))<tr><td>{{$loop->iteration}}</td><td><strong class="font-semibold text-slate-900">{{$student->full_name}}</strong><small class="block text-slate-500">NIS/NISN {{$student->nis??$student->nisn??'—'}}</small></td><td><input type="hidden" name="grades[{{$loop->index}}][student_id]" value="{{$student->id}}"><input class="input score w-24" type="number" min="0" max="100" step="0.01" name="grades[{{$loop->index}}][score]" value="{{$grade?->score}}"></td><td><span class="predicate badge badge-muted">{{$grade?->predicate??'—'}}</span></td><td><input class="input" name="grades[{{$loop->index}}][notes]" value="{{$grade?->notes}}"></td></tr>@endforeach</tbody></table>@can('academic-grades.manage')<div class="card-body"><button class="btn btn-primary w-full">Simpan Semua Nilai</button></div>@endcan</form>@endif</div><script>document.querySelectorAll('.score').forEach(i=>i.addEventListener('input',()=>{let n=parseFloat(i.value),p=i.closest('tr').querySelector('.predicate');p.textContent=isNaN(n)?'—':n>=90?'A':n>=80?'B':n>=70?'C':'D'}));</script></x-app-layout>
